      { t = "Vuelve a Rémol: entrega [Campos de pena] a Boticario Johann y acepta [Campos de pena]: lleva la calabaza al integrista Escarlata capturado, en el pueblo. Entrega [En guerra con la Cruzada Escarlata] y acepta [En guerra con la Cruzada Escarlata]; Guardia de la Muerte Burgess te da [Prueba de la muerte]. Entrega [Una nueva Peste] y acepta [Una nueva Peste].", wp = { { m = 1420, z = "Claros de Tirisfal", x = 59.5, y = 52.4, n = "Entregar: Campos de pena (Boticario Johann)", q = 365, a = "T" }, { m = 1420, z = "Claros de Tirisfal", x = 59.5, y = 52.4, n = "Recoger: Campos de pena (Boticario Johann)", q = 407, a = "A" }, { m = 1420, z = "Claros de Tirisfal", x = 62.0, y = 51.3, n = "Entregar: Campos de pena (Integrista Escarlata capturado)", q = 407, a = "T" }, { m = 1420, z = "Claros de Tirisfal", x = 60.6, y = 51.8, n = "Entregar: En guerra con la Cruzada Escarlata (Ejecutor Zygand)", q = 427, a = "T" }, { m = 1420, z = "Claros de Tirisfal", x = 60.6, y = 51.8, n = "Recoger: En guerra con la Cruzada Escarlata (Ejecutor Zygand)", q = 370, a = "A" }, { m = 1420, z = "Claros de Tirisfal", x = 60.9, y = 52.0, n = "Recoger: Prueba de la muerte (Guardia de la Muerte Burgess)", q = 374, a = "A" }, { m = 1420, z = "Claros de Tirisfal", x = 59.5, y = 52.4, n = "Entregar: Una nueva Peste (Boticario Johann)", q = 367, a = "T" }, { m = 1420, z = "Claros de Tirisfal", x = 59.5, y = 52.4, n = "Recoger: Una nueva Peste (Boticario Johann)", q = 368, a = "A" } } },
      { t = "Nivel 8: entrena con Clérico oscuro Beryl: Renovar, una cura en el tiempo y barata para después de cada combate. Gretchen Dedmar te da [El frío de la muerte] (compra el <Hilo burdo> a Abigail Shiel) y Coleman Lontananza, [Muertes en la familia] y [Los molinos fantasma]. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1420, z = "Claros de Tirisfal", x = 61.9, y = 52.7, n = "Recoger: El frío de la muerte (Gretchen Dedmar)", q = 375, a = "A" }, { m = 1420, z = "Claros de Tirisfal", x = 61.7, y = 52.3, n = "Recoger: Muertes en la familia (Coleman Lontananza)", q = 354, a = "A" }, { m = 1420, z = "Claros de Tirisfal", x = 61.7, y = 52.3, n = "Recoger: Los molinos fantasma (Coleman Lontananza)", q = 362, a = "A" }, { m = 1420, z = "Claros de Tirisfal", x = 61.6, y = 52.2, n = "Clérico oscuro Beryl", npc = 2129 } }, comprobar = { hechizos = { 139 } } },
      { t = "Paso de cadena: [Sombra durmiente] (nivel 10). Lleva la vela de la invocación a la mesa de Lillith. Sin XP base.", wp = { { m = 1420, z = "Claros de Tirisfal", x = 66.6, y = 44.9, n = "Recoger: Sombra durmiente (Mesa de cena de Lillith)", q = 410, a = "A" }, { m = 1420, z = "Claros de Tirisfal", x = 66.6, y = 44.9, n = "Entregar: Sombra durmiente (Mesa de cena de Lillith)", q = 410, a = "T" } } }, -- REFUERZO_97 q=410
      { t = "Paso de cadena: [Velas de señalización] (nivel 10). Recoge la vela para la entrega en la mesa de Lillith. Sin XP base.", wp = { { m = 1420, z = "Claros de Tirisfal", x = 68.2, y = 42, n = "Recoger: Velas de señalización (Cajón de velas)", q = 431, a = "A" }, { m = 1420, z = "Claros de Tirisfal", x = 68.2, y = 42, n = "Entregar: Velas de señalización (Cajón de velas)", q = 431, a = "T" } } }, -- REFUERZO_97 q=431

