  {
    titulo = "Molinos de Agamand y el este de Tirisfal", min = 8, max = 11,
    entrenar = "Al 10: Explosión mental (tu golpe más fuerte), Palabra de las Sombras: dolor (rango 2) y Sanación inferior (rango 3). En Entrañas, Aelthalyste te da tu misión de raza: Toque de debilidad (el próximo que te golpee recibe daño de Sombra y pega menos).",
    equipo = "[En guerra con la Cruzada Escarlata] y [En guerra con la Cruzada Escarlata] dan piezas de armadura. En Entrañas hay vendedores de telas y varitas: busca una varita en la subasta. Si subes Encantamiento, con 10 puntos te haces la <Varita mágica inferior>.",
    profesion = "En Entrañas enseñan Sastrería Víctor Tutor y Rhiannon Davis (experto; Millie Gregorian vende el hilo) y Encantamiento Malcomb Wynn y Lavinia Crowe (experto; Thaddeus Webb vende los materiales). Desencanta los verdes que no te sirvan.",
    pasos = {
      { t = "Al norte de Rémol, en los Molinos de Agamand: mata soldados armadóseos y testapartida y tirahuesos Ojosombra por las costillas y las calaveras de [La invasión de los molinos]. Los Agamand sueltan sus restos: Devlin, en el molino del sur ([Los molinos fantasma]), y Gregor, Nissa y Thurman, por los molinos ([Muertes en la familia]).", wp = { { m = 1420, z = "Claros de Tirisfal", x = 47.0, y = 35.5, n = "Objetivo: La invasión de los molinos", q = 426, a = "C" }, { m = 1420, z = "Claros de Tirisfal", x = 47.2, y = 40.0, n = "Objetivo: Los molinos fantasma", q = 362, a = "C" }, { m = 1420, z = "Claros de Tirisfal", x = 44.3, y = 31.0, n = "Objetivo: Muertes en la familia", q = 354, a = "C" } } },
      { t = "Al este de los molinos, en la cueva de los gnolls, mata a Ojo de gusano por su garra ([Se busca: Ojo de gusano]).", wp = { { m = 1420, z = "Claros de Tirisfal", x = 58.7, y = 30.8, n = "Objetivo: Se busca: Ojo de gusano", q = 398, a = "C" } } },
      { t = "Vuelve a Rémol: entrega [La invasión de los molinos], [Se busca: Ojo de gusano], [Los molinos fantasma] y [Muertes en la familia]. Entrega [Habla con Sevren] a Magistrado Sevren.", wp = { { m = 1420, z = "Claros de Tirisfal", x = 58.2, y = 51.5, n = "Entregar: La invasión de los molinos (Guardia de la Muerte Dillinger)", q = 426, a = "T" }, { m = 1420, z = "Claros de Tirisfal", x = 60.6, y = 51.8, n = "Entregar: Se busca: Ojo de gusano (Ejecutor Zygand)", q = 398, a = "T" }, { m = 1420, z = "Claros de Tirisfal", x = 61.7, y = 52.3, n = "Entregar: Los molinos fantasma (Coleman Lontananza)", q = 362, a = "T" }, { m = 1420, z = "Claros de Tirisfal", x = 61.7, y = 52.3, n = "Entregar: Muertes en la familia (Coleman Lontananza)", q = 354, a = "T" }, { m = 1420, z = "Claros de Tirisfal", x = 61.7, y = 52.3, n = "Recoger: Habla con Sevren (Coleman Lontananza)", q = 355, a = "A" }, { m = 1420, z = "Claros de Tirisfal", x = 61.3, y = 50.8, n = "Entregar: Habla con Sevren (Magistrado Sevren)", q = 355, a = "T" } } },
      { t = "Nivel 10: entrena con Clérico oscuro Beryl: Explosión mental, Palabra de las Sombras: dolor (rango 2) y Sanación inferior (rango 3). Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1420, z = "Claros de Tirisfal", x = 61.6, y = 52.2, n = "Clérico oscuro Beryl", npc = 2129 } }, comprobar = { hechizos = { 8092 } } },
      { t = "Ve al sur por el camino hasta Entrañas: Aelthalyste te da [Toque de debilidad]; entrégala: aprendes Toque de debilidad. Activa el vuelo con Michael Garrett y entrega también [El exánime pródigo] a Bethor Duroyelo. Vuelve a Rémol.", wp = { { m = 1458, z = "Entrañas", x = 49.3, y = 17.1, n = "Recoger: Toque de debilidad (Aelthalyste)", q = 5658, a = "A" }, { m = 1458, z = "Entrañas", x = 49.3, y = 17.1, n = "Entregar: Toque de debilidad (Aelthalyste)", q = 5658, a = "T" }, { m = 1458, z = "Entrañas", x = 63.2, y = 48.6, n = "Michael Garrett", npc = 4551 }, { m = 1458, z = "Entrañas", x = 84.1, y = 17.4, n = "Entregar: El exánime pródigo (Bethor Duroyelo)", q = 405, a = "T" } }, comprobar = { vuelo = "Entrañas" } },
      { t = "Al sur de Rémol mata murciumbríos superiores por el pelambre de [El frío de la muerte]. Más al oeste, al sur del camino de Camposanto, en el puesto de la Cruzada Escarlata: al Capitán Perrine, zelotes y misioneros para [En guerra con la Cruzada Escarlata]. Junta los anillos Escarlata de [Prueba de la muerte].", wp = { { m = 1420, z = "Claros de Tirisfal", x = 61.7, y = 56.8, n = "Objetivo: El frío de la muerte", q = 375, a = "C" }, { m = 1420, z = "Claros de Tirisfal", x = 51.1, y = 67.3, n = "Objetivo: En guerra con la Cruzada Escarlata", q = 370, a = "C" }, { m = 1420, z = "Claros de Tirisfal", x = 51.1, y = 67.3, n = "Objetivo: Prueba de la muerte", q = 374, a = "C" } } },
      { t = "Al oeste de Rémol, al norte de la granja Solliden: mata saltacharcos Anca Vil por las escamas de [Una nueva Peste]. Si te faltan anillos, mata más guerreros Escarlata en la granja.", wp = { { m = 1420, z = "Claros de Tirisfal", x = 34.3, y = 44.2, n = "Murlocs Anca Vil", q = 368, a = "C" }, { m = 1420, z = "Claros de Tirisfal", x = 51.1, y = 67.3, n = "Objetivo: Prueba de la muerte", q = 374, a = "C" } } },
      { t = "Vuelve a Rémol: entrega [El frío de la muerte], [En guerra con la Cruzada Escarlata], [Prueba de la muerte] y [Una nueva Peste]. Acepta [En guerra con la Cruzada Escarlata] y [Una nueva Peste]. Guardia de la Muerte Linnea, al sureste del pueblo, te da [Patrulla de la retaguardia].", wp = { { m = 1420, z = "Claros de Tirisfal", x = 61.9, y = 52.7, n = "Entregar: El frío de la muerte (Gretchen Dedmar)", q = 375, a = "T" }, { m = 1420, z = "Claros de Tirisfal", x = 60.6, y = 51.8, n = "Entregar: En guerra con la Cruzada Escarlata (Ejecutor Zygand)", q = 370, a = "T" }, { m = 1420, z = "Claros de Tirisfal", x = 60.9, y = 52.0, n = "Entregar: Prueba de la muerte (Guardia de la Muerte Burgess)", q = 374, a = "T" }, { m = 1420, z = "Claros de Tirisfal", x = 59.5, y = 52.4, n = "Entregar: Una nueva Peste (Boticario Johann)", q = 368, a = "T" }, { m = 1420, z = "Claros de Tirisfal", x = 60.6, y = 51.8, n = "Recoger: En guerra con la Cruzada Escarlata (Ejecutor Zygand)", q = 371, a = "A" }, { m = 1420, z = "Claros de Tirisfal", x = 59.5, y = 52.4, n = "Recoger: Una nueva Peste (Boticario Johann)", q = 369, a = "A" }, { m = 1420, z = "Claros de Tirisfal", x = 65.5, y = 60.2, n = "Recoger: Patrulla de la retaguardia (Guardia de la Muerte Linnea)", q = 356, a = "A" } } },
      { t = "Al este, por el camino del Baluarte: mata horrores sangrantes y espíritus deambulantes para [Patrulla de la retaguardia], al Capitán Vachon y frailes Escarlata para [En guerra con la Cruzada Escarlata], y nocturácnidas sañosas por el veneno de [Una nueva Peste], en el valle del este.", wp = { { m = 1420, z = "Claros de Tirisfal", x = 76.2, y = 60.5, n = "Objetivo: Patrulla de la retaguardia", q = 356, a = "C" }, { m = 1420, z = "Claros de Tirisfal", x = 79.2, y = 55.9, n = "Objetivo: En guerra con la Cruzada Escarlata", q = 371, a = "C" }, { m = 1420, z = "Claros de Tirisfal", x = 86.6, y = 52.3, n = "Objetivo: Una nueva Peste", q = 369, a = "C" } } },
      { t = "Vuelve a Rémol: entrega [Patrulla de la retaguardia] a Guardia de la Muerte Linnea, y [En guerra con la Cruzada Escarlata] y [Una nueva Peste]. Acepta [Una nueva Peste]: lleva el veneno al montaraz capturado, en el pueblo, y entrégala. Boticario Johann te da [Entrega a Bosque de Argénteos]: se entrega en el Bosque de Argénteos.", wp = { { m = 1420, z = "Claros de Tirisfal", x = 65.5, y = 60.2, n = "Entregar: Patrulla de la retaguardia (Guardia de la Muerte Linnea)", q = 356, a = "T" }, { m = 1420, z = "Claros de Tirisfal", x = 60.6, y = 51.8, n = "Entregar: En guerra con la Cruzada Escarlata (Ejecutor Zygand)", q = 371, a = "T" }, { m = 1420, z = "Claros de Tirisfal", x = 59.5, y = 52.4, n = "Entregar: Una nueva Peste (Boticario Johann)", q = 369, a = "T" }, { m = 1420, z = "Claros de Tirisfal", x = 59.5, y = 52.4, n = "Recoger: Una nueva Peste (Boticario Johann)", q = 492, a = "A" }, { m = 1420, z = "Claros de Tirisfal", x = 61.9, y = 51.4, n = "Entregar: Una nueva Peste (Montaraz capturado)", q = 492, a = "T" }, { m = 1420, z = "Claros de Tirisfal", x = 59.5, y = 52.4, n = "Recoger: Entrega a Bosque de Argénteos (Boticario Johann)", q = 445, a = "A" } } },

