  {
    titulo = "Bosque de Argénteos", min = 11, max = 13,
    entrenar = "Tus instructores de sacerdote en Entrañas: Aelthalyste, Padre Lankester y Padre Lazarus. Al 12: Fuego interno (más armadura) y los rangos 2 de Palabra de poder: entereza y escudo. Primer talento al 10: Sombra > Golpe de espíritu (5 puntos, del 10 al 14): después de matar recuperas maná mucho más rápido.",
    equipo = "En Entrañas hay vendedores de telas y varitas, y subasta. [Escolta a Erland] y [Ivar el Hediondo] dan piezas para tu nivel.",
    profesion = "Los humanoides del Bosque de Argénteos sueltan paño de lino y de lana: guárdalo para Sastrería y para las vendas.",
    pasos = {
      { t = "Ve al sur por el camino de Rémol, pasa junto a Entrañas y entra en el Bosque de Argénteos: sigue el camino hasta El Sepulcro. Entrega [Entrega a Bosque de Argénteos] a Boticario Renferrel. Activa el vuelo con Karos Razok. Acepta [Los Mortacechadores desaparecidos] (Sumo Ejecutor Hadrec) y [Suministros para El Sepulcro] (Guardia de la Muerte Podrig).", wp = { { m = 1421, z = "Bosque de Argénteos", x = 42.8, y = 40.9, n = "Entregar: Entrega a Bosque de Argénteos (Boticario Renferrel)", q = 445, a = "T" }, { m = 1421, z = "Bosque de Argénteos", x = 45.6, y = 42.6, n = "Karos Razok", npc = 2226 }, { m = 1421, z = "Bosque de Argénteos", x = 43.4, y = 40.9, n = "Recoger: Los Mortacechadores desaparecidos (Sumo Ejecutor Hadrec)", q = 428, a = "A" }, { m = 1421, z = "Bosque de Argénteos", x = 43.4, y = 41.7, n = "Recoger: Suministros para El Sepulcro (Guardia de la Muerte Podrig)", q = 6321, a = "A" } }, comprobar = { vuelo = "El Sepulcro" } },
      { t = "Vuelve al norte por el camino. Cerca de la frontera con Tirisfal, en el campamento de los mortacechadores, entrega [Los Mortacechadores desaparecidos] a Rane Yorick y acepta [Corazones salvajes]. Al este, Mortacechador Erland te da [Escolta a Erland]: escóltalo entre los lobos hasta Rane Yorick y entrégala; acepta [El informe de los Mortacechadores].", wp = { { m = 1421, z = "Bosque de Argénteos", x = 53.5, y = 13.4, n = "Entregar: Los Mortacechadores desaparecidos (Rane Yorick)", q = 428, a = "T" }, { m = 1421, z = "Bosque de Argénteos", x = 53.5, y = 13.4, n = "Recoger: Corazones salvajes (Rane Yorick)", q = 429, a = "A" }, { m = 1421, z = "Bosque de Argénteos", x = 56.2, y = 9.2, n = "Recoger: Escolta a Erland (Mortacechador Erland)", q = 435, a = "A" }, { m = 1421, z = "Bosque de Argénteos", x = 56.2, y = 9.2, n = "Mortacechador Erland", q = 435, a = "C" }, { m = 1421, z = "Bosque de Argénteos", x = 53.5, y = 13.4, n = "Entregar: Escolta a Erland (Rane Yorick)", q = 435, a = "T" }, { m = 1421, z = "Bosque de Argénteos", x = 53.5, y = 13.4, n = "Recoger: El informe de los Mortacechadores (Rane Yorick)", q = 449, a = "A" } } },
      { t = "Por el norte del bosque mata lupos por los corazones descoloridos de [Corazones salvajes].", wp = { { m = 1421, z = "Bosque de Argénteos", x = 59.4, y = 10.5, n = "Objetivo: Corazones salvajes", q = 429, a = "C" } } },
      { t = "Vuelve a El Sepulcro y entrega [El informe de los Mortacechadores] a Hadrec. Acepta [Habla con Renferrel], entrégala junto con [Corazones salvajes] al boticario y acepta [Vuelve con Quinn]. Al norte, entrégala a Quinn Yorick y acepta [Ojos salvajes]. Lleva tres ojos de múrloc a Renferrel, que te dará [Vuelve con Quinn (de nuevo)] y la poción. Si ya tienes los ojos, vuelve directamente a El Sepulcro. Si te faltan, búscalos en los múrlocs de la ribera del lago Lordamere.", wp = { { m = 1421, z = "Bosque de Argénteos", x = 43.4, y = 40.9, n = "Entregar: El informe de los Mortacechadores (Sumo Ejecutor Hadrec)", q = 449, a = "T" }, { m = 1421, z = "Bosque de Argénteos", x = 43.4, y = 40.9, n = "Recoger: Habla con Renferrel (Sumo Ejecutor Hadrec)", q = 3221, a = "A" }, { m = 1421, z = "Bosque de Argénteos", x = 42.8, y = 40.9, n = "Entregar: Habla con Renferrel (Boticario Renferrel)", q = 3221, a = "T" }, { m = 1421, z = "Bosque de Argénteos", x = 42.8, y = 40.9, n = "Entregar: Corazones salvajes (Boticario Renferrel)", q = 429, a = "T" }, { m = 1421, z = "Bosque de Argénteos", x = 42.8, y = 40.9, n = "Recoger: Vuelve con Quinn (Boticario Renferrel)", q = 430, a = "A" }, { m = 1421, z = "Bosque de Argénteos", x = 53.4, y = 12.6, n = "Entregar: Vuelve con Quinn (Quinn Yorick)", q = 430, a = "T" }, { m = 1421, z = "Bosque de Argénteos", x = 53.4, y = 12.7, n = "Recoger: Ojos salvajes (Quinn Yorick)", q = 91920, a = "A" }, { m = 1421, z = "Bosque de Argénteos", x = 65.1, y = 11.8, n = "Objetivo: Ojos salvajes", q = 91920, a = "C" }, { m = 1421, z = "Bosque de Argénteos", x = 42.9, y = 40.9, n = "Entregar: Ojos salvajes (Boticario Renferrel)", q = 91920, a = "T" }, { m = 1421, z = "Bosque de Argénteos", x = 42.9, y = 40.9, n = "Recoger: Vuelve con Quinn (de nuevo) (Boticario Renferrel)", q = 91921, a = "A" } } },
      { t = "Vuelve al campamento del norte y entrega la poción a Quinn Yorick en [Vuelve con Quinn (de nuevo)]. Si todavía no tienes la poción y Rane no te ofrece [Ivar el Hediondo], completa el paso anterior. Acepta la misión de Rane, mata a Ivar en la granja de al lado y entrega su cabeza.", wp = { { m = 1421, z = "Bosque de Argénteos", x = 53.4, y = 12.7, n = "Entregar: Vuelve con Quinn (de nuevo) (Quinn Yorick)", q = 91921, a = "T" }, { m = 1421, z = "Bosque de Argénteos", x = 53.5, y = 13.4, n = "Recoger: Ivar el Hediondo (Rane Yorick)", q = 425, a = "A" }, { m = 1421, z = "Bosque de Argénteos", x = 51.5, y = 13.9, n = "Objetivo: Ivar el Hediondo", q = 425, a = "C" }, { m = 1421, z = "Bosque de Argénteos", x = 53.5, y = 13.4, n = "Entregar: Ivar el Hediondo (Rane Yorick)", q = 425, a = "T" } } },
      { t = "Vuelve a El Sepulcro y entrega [Suministros para El Sepulcro] a Karos Razok: acepta [Vuela a Entrañas] y vuela a Entrañas. Entrega [Vuela a Entrañas] a Gordon Wendham y acepta [Michael Garrett]: entrégala a Michael Garrett y acepta [Vuelve con Podrig].", wp = { { m = 1421, z = "Bosque de Argénteos", x = 45.6, y = 42.6, n = "Entregar: Suministros para El Sepulcro (Karos Razok)", q = 6321, a = "T" }, { m = 1421, z = "Bosque de Argénteos", x = 45.6, y = 42.6, n = "Recoger: Vuela a Entrañas (Karos Razok)", q = 6323, a = "A" }, { m = 1458, z = "Entrañas", x = 61.5, y = 41.8, n = "Entregar: Vuela a Entrañas (Gordon Wendham)", q = 6323, a = "T" }, { m = 1458, z = "Entrañas", x = 61.5, y = 41.8, n = "Recoger: Michael Garrett (Gordon Wendham)", q = 6322, a = "A" }, { m = 1458, z = "Entrañas", x = 63.2, y = 48.6, n = "Entregar: Michael Garrett (Michael Garrett)", q = 6322, a = "T" }, { m = 1458, z = "Entrañas", x = 63.2, y = 48.6, n = "Recoger: Vuelve con Podrig (Michael Garrett)", q = 6324, a = "A" } }, comprobar = { vuelo = "Entrañas" } },
      { t = "Nivel 12: en Entrañas entrena con Aelthalyste: Fuego interno, Palabra de poder: entereza (rango 2) y Palabra de poder: escudo (rango 2). Vuela a El Sepulcro y entrega [Vuelve con Podrig] a Guardia de la Muerte Podrig. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1458, z = "Entrañas", x = 49.3, y = 17.1, n = "Aelthalyste", npc = 4606 }, { m = 1421, z = "Bosque de Argénteos", x = 43.4, y = 41.7, n = "Entregar: Vuelve con Podrig (Guardia de la Muerte Podrig)", q = 6324, a = "T" } }, comprobar = { hechizos = { 588 } } },
      { t = "Misión extra para no quedarte corto de nivel: [Una fórmula mortal] (nivel 12). Recógela, cumple los objetivos y entrégala.", wp = { { m = 1421, z = "Bosque de Argénteos", x = 42.8, y = 40.9, n = "Recoger: Una fórmula mortal (Boticario Renferrel)", q = 447, a = "A" }, { m = 1421, z = "Bosque de Argénteos", x = 35.8, y = 12.7, n = "Objetivo: Una fórmula mortal", q = 447, a = "C" }, { m = 1458, z = "Entrañas", x = 48.8, y = 69.3, n = "Entregar: Una fórmula mortal (Maestro boticario Faranell)", q = 447, a = "T" } } }, -- REFUERZO_97 q=447
      { t = "Vuela a Entrañas y sal a la superficie. Al este de Rémol, en la torre de los zepelines, coge el de Orgrimmar (Zapetta). En Durotar, entra en Orgrimmar por la puerta del sur y activa el vuelo con Doras, en la torre del Valle de la Fuerza.", wp = { { m = 1420, z = "Claros de Tirisfal", x = 60.7, y = 58.9, n = "Zapetta", npc = 9566 }, { m = 1454, z = "Orgrimmar", x = 45.1, y = 63.9, n = "Doras", npc = 3310 } }, comprobar = { vuelo = "Orgrimmar" } },
      { t = "Misión extra para no quedarte corto de nivel: [La Cripta de la Familia] (nivel 13). Recógela, cumple los objetivos y entrégala.", wp = { { m = 1420, z = "Claros de Tirisfal", x = 61.3, y = 50.8, n = "Recoger: La Cripta de la Familia (Magistrado Sevren)", q = 408, a = "A" }, { m = 1420, z = "Claros de Tirisfal", x = 52.3, y = 28.5, n = "Objetivo: La Cripta de la Familia", q = 408, a = "C" }, { m = 1420, z = "Claros de Tirisfal", x = 61.3, y = 50.8, n = "Entregar: La Cripta de la Familia (Magistrado Sevren)", q = 408, a = "T" } } }, -- REFUERZO_97 q=408
      { t = "Misión extra para no quedarte corto de nivel: [Poder destructivo] (nivel 16). Recógela, cumple los objetivos y entrégala.", wp = { { m = 1458, z = "Entrañas", x = 56.2, y = 92.2, n = "Recoger: Poder destructivo (Varimathras)", q = 5725, a = "A" }, { m = 1458, z = "Entrañas", x = 56.2, y = 92.2, n = "Entregar: Poder destructivo (Varimathras)", q = 5725, a = "T" } } }, -- REFUERZO_97 q=5725

      { t = "Misión extra en otra zona de tu nivel (Cima del Trueno): [Preparación para la ceremonia] (nivel 11). Recógela, cumple los objetivos y entrégala.", wp = { { m = 1456, z = "Cima del Trueno", x = 37.8, y = 59.6, n = "Recoger: Preparación para la ceremonia (Eyahn Garraguilar)", q = 744, a = "A" }, { m = 1456, z = "Cima del Trueno", x = 13.2, y = 23.2, n = "Objetivo: Preparación para la ceremonia", q = 744, a = "C" }, { m = 1456, z = "Cima del Trueno", x = 37.8, y = 59.6, n = "Entregar: Preparación para la ceremonia (Eyahn Garraguilar)", q = 744, a = "T" } } }, -- REFUERZO_97 q=744
    },
