  {
    titulo = "Los Baldíos: El Cruce y el Vigía Lejano", min = 13, max = 14,
    entrenar = "Primer talento al 10: Sombra > Golpe de espíritu (5 puntos, del 10 al 14): después de matar recuperas maná mucho más rápido. En Los Baldíos no hay instructor de sacerdote: vuelve a Orgrimmar (Ur'kyo) cada dos niveles. Al 12: Fuego interno (más armadura) y los rangos 2 de Palabra de poder: entereza y escudo.",
    equipo = "Las misiones de El Cruce dan piezas de tela. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Kil'hala, en El Cruce, enseña Sastrería hasta oficial y Wrahk, al lado, vende el hilo. Pon la piedra de hogar en El Cruce.",
    pasos = {
      { t = "Sal de Orgrimmar por la puerta del oeste, cruza el puente del río al Puesto del Vigía Lejano y sigue el camino al sur hasta El Cruce. Sergra Espinoscura te da [La amenaza de los zancudos de llanura]. Acepta también [Acabar con los ataques de los Crines de Acero] y [Suministros para El Cruce] (Thork), [Los raptores ladrones] (Gazrog), [Esporas de hongos] (Boticario Helbrim) y [Las Charcas del Olvido] (Tonga Tótem de Runa). Pon la piedra de hogar con Tabernero Boorand Ventollano y activa el vuelo con Devrak.", wp = { { m = 1413, z = "Los Baldíos", x = 52.2, y = 31.0, n = "Recoger: La amenaza de los zancudos de llanura (Sergra Espinoscura)", q = 844, a = "A" }, { m = 1413, z = "Los Baldíos", x = 51.5, y = 30.9, n = "Recoger: Acabar con los ataques de los Crines de Acero (Thork)", q = 871, a = "A" }, { m = 1413, z = "Los Baldíos", x = 51.5, y = 30.9, n = "Recoger: Suministros para El Cruce (Thork)", q = 5041, a = "A" }, { m = 1413, z = "Los Baldíos", x = 51.9, y = 30.3, n = "Recoger: Los raptores ladrones (Gazrog)", q = 869, a = "A" }, { m = 1413, z = "Los Baldíos", x = 51.4, y = 30.1, n = "Recoger: Esporas de hongos (Boticario Helbrim)", q = 848, a = "A" }, { m = 1413, z = "Los Baldíos", x = 52.3, y = 31.9, n = "Recoger: Las Charcas del Olvido (Tonga Tótem de Runa)", q = 870, a = "A" }, { m = 1413, z = "Los Baldíos", x = 52.0, y = 29.9, n = "Tabernero Boorand Ventollano", npc = 3934 }, { m = 1413, z = "Los Baldíos", x = 51.5, y = 30.3, n = "Devrak", npc = 3615 } }, comprobar = { vuelo = "El Cruce" } },
      { t = "Por el mismo camino, en los campamentos de los Crines de Acero del nordeste: mata buscaquas, tejespinas y cazadores para [Acabar con los ataques de los Crines de Acero] y recoge los cajones de suministros para [Suministros para El Cruce]. Mata zancudos de llanura para [La amenaza de los zancudos de llanura] por el camino.", wp = { { m = 1413, z = "Los Baldíos", x = 55.3, y = 25.8, n = "Objetivo: Acabar con los ataques de los Crines de Acero", q = 871, a = "C" }, { m = 1413, z = "Los Baldíos", x = 59.0, y = 25.8, n = "Objetivo: Suministros para El Cruce", q = 5041, a = "C" }, { m = 1413, z = "Los Baldíos", x = 53.1, y = 31.3, n = "Objetivo: La amenaza de los zancudos de llanura", q = 844, a = "C" } } },
      { t = "Vuelve a El Cruce: entrega [Acabar con los ataques de los Crines de Acero], [Suministros para El Cruce] y [La amenaza de los zancudos de llanura]. Acepta [El fin de las hostilidades] y [El astacebra].", wp = { { m = 1413, z = "Los Baldíos", x = 51.5, y = 30.9, n = "Entregar: Acabar con los ataques de los Crines de Acero (Thork)", q = 871, a = "T" }, { m = 1413, z = "Los Baldíos", x = 51.5, y = 30.9, n = "Entregar: Suministros para El Cruce (Thork)", q = 5041, a = "T" }, { m = 1413, z = "Los Baldíos", x = 52.2, y = 31.0, n = "Entregar: La amenaza de los zancudos de llanura (Sergra Espinoscura)", q = 844, a = "T" }, { m = 1413, z = "Los Baldíos", x = 51.5, y = 30.9, n = "Recoger: El fin de las hostilidades (Thork)", q = 872, a = "A" }, { m = 1413, z = "Los Baldíos", x = 52.2, y = 31.0, n = "Recoger: El astacebra (Sergra Espinoscura)", q = 845, a = "A" } } },
      { t = "Al noroeste, en las Charcas del Olvido, explora el agua para [Las Charcas del Olvido] y recoge los champiñones de [Esporas de hongos]. Mata astacebras para [El astacebra].", wp = { { m = 1413, z = "Los Baldíos", x = 45.1, y = 22.5, n = "Objetivo: Las Charcas del Olvido", q = 870, a = "C" }, { m = 1413, z = "Los Baldíos", x = 46.6, y = 39.4, n = "Objetivo: Esporas de hongos", q = 848, a = "C" }, { m = 1413, z = "Los Baldíos", x = 52.0, y = 36.4, n = "Objetivo: El astacebra", q = 845, a = "C" } } },
      { t = "De vuelta, mata al jefe Kreenig Gruñucico y a geománticos y defensores Crines de Acero, al este del camino, para [El fin de las hostilidades].", wp = { { m = 1413, z = "Los Baldíos", x = 58.3, y = 25.2, n = "Objetivo: El fin de las hostilidades", q = 872, a = "C" } } },
      { t = "En El Cruce entrega [El fin de las hostilidades], [El astacebra], [Las Charcas del Olvido] y [Esporas de hongos]. Acepta [Merodeadores de los Baldíos] y [El Oasis Estancado].", wp = { { m = 1413, z = "Los Baldíos", x = 51.5, y = 30.9, n = "Entregar: El fin de las hostilidades (Thork)", q = 872, a = "T" }, { m = 1413, z = "Los Baldíos", x = 52.2, y = 31.0, n = "Entregar: El astacebra (Sergra Espinoscura)", q = 845, a = "T" }, { m = 1413, z = "Los Baldíos", x = 52.3, y = 31.9, n = "Entregar: Las Charcas del Olvido (Tonga Tótem de Runa)", q = 870, a = "T" }, { m = 1413, z = "Los Baldíos", x = 51.4, y = 30.1, n = "Entregar: Esporas de hongos (Boticario Helbrim)", q = 848, a = "T" }, { m = 1413, z = "Los Baldíos", x = 52.2, y = 31.0, n = "Recoger: Merodeadores de los Baldíos (Sergra Espinoscura)", q = 903, a = "A" }, { m = 1413, z = "Los Baldíos", x = 52.3, y = 31.9, n = "Recoger: El Oasis Estancado (Tonga Tótem de Runa)", q = 877, a = "A" } } },
      { t = "Nivel 12: vuela a Orgrimmar y entrena con Ur'kyo, en el Valle de los Espíritus: Fuego interno, Palabra de poder: entereza (rango 2) y Palabra de poder: escudo (rango 2). Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1454, z = "Orgrimmar", x = 35.6, y = 87.8, n = "Ur'kyo", npc = 6018 } }, comprobar = { hechizos = { 588 } } },

    },
  },
  {
    titulo = "Los Baldíos: Trinquete y el Oasis", min = 14, max = 18,
    entrenar = "Al 14: Alarido psíquico (asusta a los que tienes cerca) y Renovar (rango 2). Talentos 15-16: Palabra de las Sombras: dolor mejorada.",
    equipo = "En Trinquete hay vendedores de armas y armaduras. [El botín robado] da buenas piezas para tu nivel. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Haz <Madeja de paño de lino> con el paño de lino y desencanta los verdes que no te sirvan: el polvo y las esencias suben Encantamiento.",
    pasos = {
      { t = "Al este, por el camino de Trinquete: mata raptores para [Los raptores ladrones] y merodeadores de la sabana para [Merodeadores de los Baldíos]. Las cabezas también caen de los raptores de la costa.", wp = { { m = 1413, z = "Los Baldíos", x = 55.8, y = 44.6, n = "Objetivo: Los raptores ladrones", q = 869, a = "C" }, { m = 1413, z = "Los Baldíos", x = 42.7, y = 32.0, n = "Objetivo: Merodeadores de los Baldíos", q = 903, a = "C" } } },
      { t = "En Trinquete activa el vuelo con Bragok y acepta [Los filibusteros del Mar del Sur] (Gazlowe). En la costa sur del pueblo mata brigadieres y cañoneros del Mar del Sur para [Los filibusteros del Mar del Sur].", wp = { { m = 1413, z = "Los Baldíos", x = 63.1, y = 37.2, n = "Bragok", npc = 16227 }, { m = 1413, z = "Los Baldíos", x = 62.7, y = 36.2, n = "Recoger: Los filibusteros del Mar del Sur (Gazlowe)", q = 887, a = "A" }, { m = 1413, z = "Los Baldíos", x = 63.7, y = 46.9, n = "Objetivo: Los filibusteros del Mar del Sur", q = 887, a = "C" } }, comprobar = { vuelo = "Trinquete" } },
      { t = "Entrega [Los filibusteros del Mar del Sur] y acepta [El envío perdido]: llévala a Maestro de muelles Vertipeluca, en el muelle, que te da [El envío perdido]. Entrégala a Gazlowe y acepta [El botín robado]: en el campamento pirata del sur, el envío de botas y las lentes telescópicas.", wp = { { m = 1413, z = "Los Baldíos", x = 62.7, y = 36.2, n = "Entregar: Los filibusteros del Mar del Sur (Gazlowe)", q = 887, a = "T" }, { m = 1413, z = "Los Baldíos", x = 62.7, y = 36.2, n = "Recoger: El envío perdido (Gazlowe)", q = 890, a = "A" }, { m = 1413, z = "Los Baldíos", x = 63.4, y = 38.5, n = "Entregar: El envío perdido (Maestro de muelles Vertipeluca)", q = 890, a = "T" }, { m = 1413, z = "Los Baldíos", x = 63.4, y = 38.5, n = "Recoger: El envío perdido (Maestro de muelles Vertipeluca)", q = 892, a = "A" }, { m = 1413, z = "Los Baldíos", x = 62.7, y = 36.2, n = "Entregar: El envío perdido (Gazlowe)", q = 892, a = "T" }, { m = 1413, z = "Los Baldíos", x = 62.7, y = 36.2, n = "Recoger: El botín robado (Gazlowe)", q = 888, a = "A" }, { m = 1413, z = "Los Baldíos", x = 63.1, y = 49.4, n = "Objetivo: El botín robado", q = 888, a = "C" }, { m = 1413, z = "Los Baldíos", x = 62.7, y = 36.2, n = "Entregar: El botín robado (Gazlowe)", q = 888, a = "T" } } },
      { t = "En la Fisura burbujeante del Oasis Estancado (suroeste de Trinquete) usa el vial para [El Oasis Estancado] y mata quijafortes alterados del agua. Al lado está la plata robada de [La plata robada] (te la da Gazrog al entregar [Los raptores ladrones]).", wp = { { m = 1413, z = "Los Baldíos", x = 55.6, y = 42.8, n = "Objetivo: El Oasis Estancado", q = 877, a = "C" } } },
      { t = "Vuelve a El Cruce: entrega [Los raptores ladrones], [Merodeadores de los Baldíos] y [El Oasis Estancado]. Acepta [La plata robada], [Echeyakee] y [Fuentes de vida].", wp = { { m = 1413, z = "Los Baldíos", x = 51.9, y = 30.3, n = "Entregar: Los raptores ladrones (Gazrog)", q = 869, a = "T" }, { m = 1413, z = "Los Baldíos", x = 52.2, y = 31.0, n = "Entregar: Merodeadores de los Baldíos (Sergra Espinoscura)", q = 903, a = "T" }, { m = 1413, z = "Los Baldíos", x = 52.3, y = 31.9, n = "Entregar: El Oasis Estancado (Tonga Tótem de Runa)", q = 877, a = "T" }, { m = 1413, z = "Los Baldíos", x = 51.9, y = 30.3, n = "Recoger: La plata robada (Gazrog)", q = 3281, a = "A" }, { m = 1413, z = "Los Baldíos", x = 52.2, y = 31.0, n = "Recoger: Echeyakee (Sergra Espinoscura)", q = 881, a = "A" }, { m = 1413, z = "Los Baldíos", x = 52.3, y = 31.9, n = "Recoger: Fuentes de vida (Tonga Tótem de Runa)", q = 880, a = "A" } } },
      { t = "Al nordeste, Echeyakee (león blanco) aparece al usar el cuerno en la guarida de los leones ([Echeyakee]).", wp = { { m = 1413, z = "Los Baldíos", x = 55.9, y = 17.2, n = "Objetivo: Echeyakee", q = 881, a = "C" } } },
      { t = "De vuelta al sur, mata quijafortes alterados en los oasis para [Fuentes de vida] y recoge la plata robada del oasis para [La plata robada].", wp = { { m = 1413, z = "Los Baldíos", x = 46.8, y = 39.7, n = "Objetivo: Fuentes de vida", q = 880, a = "C" }, { m = 1413, z = "Los Baldíos", x = 58.0, y = 53.9, n = "Objetivo: La plata robada", q = 3281, a = "C" } } },
