  {
    titulo = "Los Baldíos: Kolkar, arpías y Taurajo", min = 16, max = 20,
    entrenar = "Al 16: Sanar y Explosión mental (rango 2); al 18, Palabra de las Sombras: dolor (rango 3) y Palabra de poder: escudo (rango 3). Talentos 17-19: Explosión mental mejorada.",
    equipo = "[Hezrul Marcasangre] y [Serena Sangrepluma] dan piezas buenas. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "Al 20, con 125, aprende el rango experto de Sastrería con Magar (Orgrimmar) o Mahani (Taurajo) y el de Encantamiento con Godan (Orgrimmar).",
    pasos = {
      { t = "En El Cruce acepta [Los brazales de centauro] y [Los jefes de Kolkar] a Regthar Portamorta (al noroeste, en el puesto de Regthar), [Arpías saqueadoras] (Darsok Movedaga) y [Consumido por el odio] y [Perdida en la batalla] (Mankrik).", wp = { { m = 1413, z = "Los Baldíos", x = 45.3, y = 28.4, n = "Recoger: Los brazales de centauro (Regthar Portamorta)", q = 855, a = "A" }, { m = 1413, z = "Los Baldíos", x = 45.3, y = 28.4, n = "Recoger: Los jefes de Kolkar (Regthar Portamorta)", q = 850, a = "A" }, { m = 1413, z = "Los Baldíos", x = 51.6, y = 30.9, n = "Recoger: Arpías saqueadoras (Darsok Movedaga)", q = 867, a = "A" }, { m = 1413, z = "Los Baldíos", x = 52.0, y = 31.6, n = "Recoger: Consumido por el odio (Mankrik)", q = 899, a = "A" }, { m = 1413, z = "Los Baldíos", x = 52.0, y = 31.6, n = "Recoger: Perdida en la batalla (Mankrik)", q = 4921, a = "A" } } },
      { t = "Al oeste de El Cruce, en los campamentos Kolkar: mata centauros por los brazales de [Los brazales de centauro] y a Barak Aterrakodos ([Los jefes de Kolkar]). Entrega las dos y acepta [Verog el Derviche].", wp = { { m = 1413, z = "Los Baldíos", x = 44.5, y = 23.9, n = "Objetivo: Los brazales de centauro", q = 855, a = "C" }, { m = 1413, z = "Los Baldíos", x = 42.8, y = 23.5, n = "Objetivo: Los jefes de Kolkar", q = 850, a = "C" }, { m = 1413, z = "Los Baldíos", x = 45.3, y = 28.4, n = "Entregar: Los brazales de centauro (Regthar Portamorta)", q = 855, a = "T" }, { m = 1413, z = "Los Baldíos", x = 45.3, y = 28.4, n = "Entregar: Los jefes de Kolkar (Regthar Portamorta)", q = 850, a = "T" }, { m = 1413, z = "Los Baldíos", x = 45.3, y = 28.4, n = "Recoger: Verog el Derviche (Regthar Portamorta)", q = 851, a = "A" } } },
      { t = "Al noroeste, en el Desfiladero Viento Seco: arpías ala de bruja para [Arpías saqueadoras]. Entrega y acepta [Las tenientes arpías]: las tenientes arpías del mismo desfiladero.", wp = { { m = 1413, z = "Los Baldíos", x = 39.6, y = 15.4, n = "Objetivo: Arpías saqueadoras", q = 867, a = "C" }, { m = 1413, z = "Los Baldíos", x = 51.6, y = 30.9, n = "Entregar: Arpías saqueadoras (Darsok Movedaga)", q = 867, a = "T" }, { m = 1413, z = "Los Baldíos", x = 51.6, y = 30.9, n = "Recoger: Las tenientes arpías (Darsok Movedaga)", q = 875, a = "A" }, { m = 1413, z = "Los Baldíos", x = 38.9, y = 14.5, n = "Objetivo: Las tenientes arpías", q = 875, a = "C" }, { m = 1413, z = "Los Baldíos", x = 51.6, y = 30.9, n = "Entregar: Las tenientes arpías (Darsok Movedaga)", q = 875, a = "T" } } },
      { t = "Nivel 16: vuela a Orgrimmar y entrena con Ur'kyo, en el Valle de los Espíritus: Sanar y Explosión mental (rango 2). Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1454, z = "Orgrimmar", x = 35.6, y = 87.8, n = "Ur'kyo", npc = 6018 } }, comprobar = { hechizos = { 8102 } } },
      { t = "En la cima del desfiladero mata a Serena Sangrepluma ([Serena Sangrepluma], mejor en grupo). Entrégala en El Cruce y acepta [Una carta para Jin'Zil]: es para Sierra Espolón.", wp = { { m = 1413, z = "Los Baldíos", x = 51.6, y = 30.9, n = "Recoger: Serena Sangrepluma (Darsok Movedaga)", q = 876, a = "A" }, { m = 1413, z = "Los Baldíos", x = 39.2, y = 12.2, n = "Objetivo: Serena Sangrepluma", q = 876, a = "C" }, { m = 1413, z = "Los Baldíos", x = 51.6, y = 30.9, n = "Entregar: Serena Sangrepluma (Darsok Movedaga)", q = 876, a = "T" }, { m = 1413, z = "Los Baldíos", x = 51.6, y = 30.9, n = "Recoger: Una carta para Jin'Zil (Darsok Movedaga)", q = 1060, a = "A" } } },
      { t = "Al sur de El Cruce, en el Oasis Estancado, mata a Verog el Derviche ([Verog el Derviche]). Entrega y acepta [Hezrul Marcasangre]: Hezrul Marcasangre, en el oasis del oeste.", wp = { { m = 1413, z = "Los Baldíos", x = 53.1, y = 41.7, n = "Objetivo: Verog el Derviche", q = 851, a = "C" }, { m = 1413, z = "Los Baldíos", x = 45.3, y = 28.4, n = "Entregar: Verog el Derviche (Regthar Portamorta)", q = 851, a = "T" }, { m = 1413, z = "Los Baldíos", x = 45.3, y = 28.4, n = "Recoger: Hezrul Marcasangre (Regthar Portamorta)", q = 852, a = "A" }, { m = 1413, z = "Los Baldíos", x = 46.0, y = 41.1, n = "Objetivo: Hezrul Marcasangre", q = 852, a = "C" }, { m = 1413, z = "Los Baldíos", x = 45.3, y = 28.4, n = "Entregar: Hezrul Marcasangre (Regthar Portamorta)", q = 852, a = "T" } } },
      { t = "Lleva los nidos de raptor de [La ira de los segadores] al sur del Oasis de los Baldíos (52,46): toca los tres nidos de colores. Entrégala y acepta [Jorn Visioceleste].", wp = { { m = 1413, z = "Los Baldíos", x = 52.4, y = 46.4, n = "Objetivo: La ira de los segadores", q = 905, a = "C" }, { m = 1413, z = "Los Baldíos", x = 52.2, y = 31.0, n = "Entregar: La ira de los segadores (Sergra Espinoscura)", q = 905, a = "T" }, { m = 1413, z = "Los Baldíos", x = 52.2, y = 31.0, n = "Recoger: Jorn Visioceleste (Sergra Espinoscura)", q = 3261, a = "A" } } },
      { t = "Baja por el camino hasta Campamento Taurajo: entrega [Jorn Visioceleste] a Jorn Vidente del Cielo y acepta [Ishamuhale]. Activa el vuelo con Omusa Tronacuerno y pon la piedra de hogar con Tabernera Byula.", wp = { { m = 1413, z = "Los Baldíos", x = 44.9, y = 59.1, n = "Entregar: Jorn Visioceleste (Jorn Vidente del Cielo)", q = 3261, a = "T" }, { m = 1413, z = "Los Baldíos", x = 44.9, y = 59.1, n = "Recoger: Ishamuhale (Jorn Vidente del Cielo)", q = 882, a = "A" }, { m = 1413, z = "Los Baldíos", x = 44.5, y = 59.1, n = "Omusa Tronacuerno", npc = 10378 }, { m = 1413, z = "Los Baldíos", x = 45.6, y = 59.0, n = "Tabernera Byula", npc = 7714 } }, comprobar = { vuelo = "Taurajo" } },
      { t = "Al este de El Cruce mata a Ishamuhale, el raptor grande, por el colmillo de [Ishamuhale]. Entrégalo en Taurajo y acepta [La rabia de los truenagartos]: sangre de truenagartos al oeste de Taurajo.", wp = { { m = 1413, z = "Los Baldíos", x = 59.8, y = 30.6, n = "Objetivo: Ishamuhale", q = 882, a = "C" }, { m = 1413, z = "Los Baldíos", x = 44.9, y = 59.1, n = "Entregar: Ishamuhale (Jorn Vidente del Cielo)", q = 882, a = "T" }, { m = 1413, z = "Los Baldíos", x = 44.9, y = 59.1, n = "Recoger: La rabia de los truenagartos (Jorn Vidente del Cielo)", q = 907, a = "A" }, { m = 1413, z = "Los Baldíos", x = 47.8, y = 59.2, n = "Objetivo: La rabia de los truenagartos", q = 907, a = "C" }, { m = 1413, z = "Los Baldíos", x = 44.9, y = 59.1, n = "Entregar: La rabia de los truenagartos (Jorn Vidente del Cielo)", q = 907, a = "T" } } },
      { t = "Junto a la Gran Puerta, al este de Taurajo, mata jabaespines Lomopelo para [Consumido por el odio] y busca el cadáver de Mankrik en el campamento ([Perdida en la batalla]). Entrega las dos en El Cruce.", wp = { { m = 1413, z = "Los Baldíos", x = 48.4, y = 52.6, n = "Objetivo: Consumido por el odio", q = 899, a = "C" }, { m = 1413, z = "Los Baldíos", x = 49.3, y = 50.3, n = "Objetivo: Perdida en la batalla", q = 4921, a = "C" }, { m = 1413, z = "Los Baldíos", x = 52.0, y = 31.6, n = "Entregar: Consumido por el odio (Mankrik)", q = 899, a = "T" }, { m = 1413, z = "Los Baldíos", x = 52.0, y = 31.6, n = "Entregar: Perdida en la batalla (Mankrik)", q = 4921, a = "T" } } },
