      { t = "Al oeste del refugio, en el valle de las arpías, mata arpías Furia Sangrienta para [La ameneza de la arpías]. Entrega y acepta [El linaje Furia Sangrienta]: mata a la Destripadora del fondo del valle por sus restos.", wp = { { m = 1442, z = "Sierra Espolón", x = 32.9, y = 66.0, n = "Objetivo: La ameneza de la arpías", q = 6282, a = "C" }, { m = 1442, z = "Sierra Espolón", x = 47.2, y = 61.2, n = "Entregar: La ameneza de la arpías (Ligaterra Maggram)", q = 6282, a = "T" }, { m = 1442, z = "Sierra Espolón", x = 47.2, y = 61.2, n = "Recoger: El linaje Furia Sangrienta (Ligaterra Maggram)", q = 6283, a = "A" }, { m = 1442, z = "Sierra Espolón", x = 30.8, y = 61.9, n = "Objetivo: El linaje Furia Sangrienta", q = 6283, a = "C" }, { m = 1442, z = "Sierra Espolón", x = 47.2, y = 61.2, n = "Entregar: El linaje Furia Sangrienta (Ligaterra Maggram)", q = 6283, a = "T" } } },
      { t = "Junto al lago del refugio recoge las semillas de Gaea ([El ciclo del renacimiento]). Entrega y acepta [Nueva vida]: planta las semillas en los túmulos del suroeste.", wp = { { m = 1442, z = "Sierra Espolón", x = 48.8, y = 40.7, n = "Objetivo: El ciclo del renacimiento", q = 6301, a = "C" }, { m = 1442, z = "Sierra Espolón", x = 47.5, y = 58.4, n = "Entregar: El ciclo del renacimiento (Tammra Campovento)", q = 6301, a = "T" }, { m = 1442, z = "Sierra Espolón", x = 47.5, y = 58.4, n = "Recoger: Nueva vida (Tammra Campovento)", q = 6381, a = "A" }, { m = 1442, z = "Sierra Espolón", x = 33.1, y = 68.0, n = "Objetivo: Nueva vida", q = 6381, a = "C" }, { m = 1442, z = "Sierra Espolón", x = 47.5, y = 58.4, n = "Entregar: Nueva vida (Tammra Campovento)", q = 6381, a = "T" } } },
      { t = "Mata elementales de fuego del este (incendritas) para [Guerra elemental] y entrégala en el refugio.", wp = { { m = 1442, z = "Sierra Espolón", x = 32.2, y = 70.7, n = "Objetivo: Guerra elemental", q = 6393, a = "C" }, { m = 1442, z = "Sierra Espolón", x = 47.4, y = 64.2, n = "Entregar: Guerra elemental (Tsunaman)", q = 6393, a = "T" } } },
      { t = "Al este de la sierra, en el Bosque Talado (Ventura y Cía.), mata leñeros para [Los invasores goblin]. Mata también rufianes y mercenarios Tótem Siniestro en el Pueblo Maleza para [Venga mi aldea].", wp = { { m = 1442, z = "Sierra Espolón", x = 66.2, y = 52.5, n = "Objetivo: Los invasores goblin", q = 1062, a = "C" }, { m = 1442, z = "Sierra Espolón", x = 82.2, y = 87.3, n = "Objetivo: Venga mi aldea", q = 6548, a = "C" } } },
      { t = "Al sur, en el Campamento Malaka'jin, Médico brujo Jin'Zil recibe [Una carta para Jin'Zil] y te da [Magia del bosque de Jin'Zil]. Acepta también [Chupasangres] (Xen'Zilla): mata trepadores y escupevenenos Musgondo.", wp = { { m = 1442, z = "Sierra Espolón", x = 74.5, y = 97.9, n = "Entregar: Una carta para Jin'Zil (Médico brujo Jin'Zil)", q = 1060, a = "T" }, { m = 1442, z = "Sierra Espolón", x = 74.5, y = 97.9, n = "Recoger: Magia del bosque de Jin'Zil (Médico brujo Jin'Zil)", q = 1058, a = "A" }, { m = 1442, z = "Sierra Espolón", x = 71.2, y = 95.0, n = "Recoger: Chupasangres (Xen'Zilla)", q = 6461, a = "A" }, { m = 1442, z = "Sierra Espolón", x = 55.3, y = 74.7, n = "Objetivo: Chupasangres", q = 6461, a = "C" }, { m = 1442, z = "Sierra Espolón", x = 71.2, y = 95.0, n = "Entregar: Chupasangres (Xen'Zilla)", q = 6461, a = "T" } } },
      { t = "Para [Magia del bosque de Jin'Zil] junta salvia del Espolón, mostacho del Crepúsculo, ojos de corcel y escamas de dragón Fey en el sur de la sierra. Entrégala en Malaka'jin.", wp = { { m = 1442, z = "Sierra Espolón", x = 36.9, y = 15.7, n = "Objetivo: Magia del bosque de Jin'Zil", q = 1058, a = "C" }, { m = 1442, z = "Sierra Espolón", x = 74.5, y = 97.9, n = "Entregar: Magia del bosque de Jin'Zil (Médico brujo Jin'Zil)", q = 1058, a = "T" } } },
      { t = "Vuelve al puesto de Los Baldíos y entrega [Los invasores goblin] y [Venga mi aldea].", wp = { { m = 1413, z = "Los Baldíos", x = 35.3, y = 27.9, n = "Entregar: Los invasores goblin (Seereth Rompepedras)", q = 1062, a = "T" }, { m = 1413, z = "Los Baldíos", x = 35.2, y = 27.8, n = "Entregar: Venga mi aldea (Makaba Patatleta)", q = 6548, a = "T" } } },
      { t = "Nivel 20: vuela a Orgrimmar y coge el zepelín a Entrañas (torre al este de la ciudad, fuera de la muralla). Entrena con Aelthalyste: Sanación relámpago, Peste devoradora, Fuego interno (rango 2) y Renovar (rango 3). Acepta y entrega [Sacrificio oscuro]: aprendes tu hechizo de raza del 20, Sacrificio oscuro (nuevo en Forever). Vuelve en zepelín a Orgrimmar. Al hablar con el instructor elige entrenar: la guía aprende sola lo recomendado (Mayús para hacerlo a mano).", wp = { { m = 1458, z = "Entrañas", x = 49.3, y = 17.1, n = "Aelthalyste", npc = 4606 }, { m = 1458, z = "Entrañas", x = 49.3, y = 17.1, n = "Recoger: Sacrificio oscuro (Aelthalyste)", q = 5679, a = "A" }, { m = 1458, z = "Entrañas", x = 49.3, y = 17.1, n = "Entregar: Sacrificio oscuro (Aelthalyste)", q = 5679, a = "T" } }, comprobar = { hechizos = { 2061 } } },

      { t = "Misión extra en otra zona de tu nivel (Laderas de Trabalomas): [La batalla de Trabalomas] (nivel 24). Recógela, cumple los objetivos y entrégala.", wp = { { m = 1424, z = "Laderas de Trabalomas", x = 62.3, y = 20.4, n = "Recoger: La batalla de Trabalomas (Suma ejecutora Darthalia)", q = 527, a = "A" }, { m = 1424, z = "Laderas de Trabalomas", x = 33.6, y = 38.7, n = "Objetivo: La batalla de Trabalomas", q = 527, a = "C" }, { m = 1424, z = "Laderas de Trabalomas", x = 62.3, y = 20.4, n = "Entregar: La batalla de Trabalomas (Suma ejecutora Darthalia)", q = 527, a = "T" } } }, -- REFUERZO_97 q=527
