      { t = "Junta fragmentos de sangre de los Erizapúas para [Fragmentos ensangrentados de Agamaggan] y entrégala.", wp = { { m = 1413, z = "Los Baldíos", x = 47.9, y = 54.1, n = "Objetivo: Fragmentos ensangrentados de Agamaggan", q = 5052, a = "C" }, { m = 1413, z = "Los Baldíos", x = 44.5, y = 59.3, n = "Entregar: Fragmentos ensangrentados de Agamaggan (Quebrantadientes)", q = 5052, a = "T" }, { m = 1413, z = "Los Baldíos", x = 44.5, y = 59.3, n = "Recoger: Traidores (Quebrantadientes)", q = 879, a = "A" } } },
      { t = "Al sureste de Taurajo, en Bael Modan, Gann Aguja de Piedra te da [La reclamación de Gann]: mata excavadores y supervisores de Bael'dun y al prospector Khazgorm por su diario. Entrega y acepta [La venganza de Gann].", wp = { { m = 1413, z = "Los Baldíos", x = 45.9, y = 77.0, n = "Recoger: La reclamación de Gann (Gann Aguja de Piedra)", q = 843, a = "A" }, { m = 1413, z = "Los Baldíos", x = 47.6, y = 85.2, n = "Objetivo: La reclamación de Gann", q = 843, a = "C" }, { m = 1413, z = "Los Baldíos", x = 45.9, y = 77.0, n = "Entregar: La reclamación de Gann (Gann Aguja de Piedra)", q = 843, a = "T" }, { m = 1413, z = "Los Baldíos", x = 45.9, y = 77.0, n = "Recoger: La venganza de Gann (Gann Aguja de Piedra)", q = 846, a = "A" }, { m = 1413, z = "Los Baldíos", x = 49.1, y = 84.2, n = "Objetivo: La venganza de Gann", q = 846, a = "C" }, { m = 1413, z = "Los Baldíos", x = 45.9, y = 77.0, n = "Entregar: La venganza de Gann (Gann Aguja de Piedra)", q = 846, a = "T" }, { m = 1413, z = "Los Baldíos", x = 45.9, y = 77.0, n = "Recoger: La venganza de Gann (Gann Aguja de Piedra)", q = 849, a = "A" }, { m = 1413, z = "Los Baldíos", x = 47.0, y = 85.6, n = "Objetivo: La venganza de Gann", q = 849, a = "C" }, { m = 1413, z = "Los Baldíos", x = 45.9, y = 77.0, n = "Entregar: La venganza de Gann (Gann Aguja de Piedra)", q = 849, a = "T" } } },
      { t = "Al sur de la Gran Puerta, en las tres madrigueras de los Erizapúas, mata a Kuz, Nak y Lok Aterraorcos por sus calaveras ([Traidores]). Entrega y acepta [Traidores]: se entrega en El Cruce.", wp = { { m = 1413, z = "Los Baldíos", x = 43.0, y = 81.3, n = "Objetivo: Traidores", q = 879, a = "C" }, { m = 1413, z = "Los Baldíos", x = 44.5, y = 59.3, n = "Entregar: Traidores (Quebrantadientes)", q = 879, a = "T" }, { m = 1413, z = "Los Baldíos", x = 44.5, y = 59.3, n = "Recoger: Traidores (Quebrantadientes)", q = 906, a = "A" } } },
