  {
    titulo = "Laderas de Trabalomas, Alterac y Arathi", min = 32, max = 35,
    entrenar = "Al 34: Explosión mental (rango 5) y Palabra de las Sombras: dolor (rango 5). En los Reinos del Este tienes instructor de sacerdote en Entrañas: Aelthalyste. Talentos: 33 Alcance de las Sombras (2/2) y 34 Enfoque de las Sombras.",
    equipo = "Las misiones de Sentencia dan piezas de tela. Con grupo: Monasterio Escarlata (Biblioteca, 30-35). Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "En Sentencia (Arathi), Doctor Gregory Victor hace [Orden de gravedad] a 225 de Primeros auxilios. En el Molino Tarren, Daryl Stack es maestro sastre.",
    pasos = {
      { t = "En Orgrimmar coge el zepelín a Entrañas (torre al este de la ciudad, fuera de la muralla). En Entrañas activa el vuelo con Michael Garrett. Sigue a pie al sur por el Bosque de Argénteos (activa el vuelo de Sepulcro con Karos Razok) hasta el Molino Tarren, en las Laderas de Trabalomas: activa el vuelo con Zarise y pon allí la piedra de hogar con Tabernero Shay.", wp = { { m = 1458, z = "Entrañas", x = 63.2, y = 48.6, n = "Michael Garrett", npc = 4551 }, { m = 1421, z = "Bosque de Argénteos", x = 45.6, y = 42.6, n = "Karos Razok", npc = 2226 }, { m = 1424, z = "Laderas de Trabalomas", x = 60.1, y = 18.6, n = "Zarise", npc = 2389 }, { m = 1424, z = "Laderas de Trabalomas", x = 62.8, y = 19.0, n = "Tabernero Shay", npc = 2388 } }, comprobar = { vuelo = "Molino Tarren" } },
      { t = "En el Molino Tarren acepta [La venganza de Helcular] (Novicio Thaivand), [Muestras de piedra] (Vigilante Bel'varil), [Colarse en la cárcel] y [La llave de la ciudad] (Magus Wordeen Vacuamirada), y [La Sentencia] (Sebo).", wp = { { m = 1424, z = "Laderas de Trabalomas", x = 63.9, y = 19.7, n = "Recoger: La venganza de Helcular (Novicio Thaivand)", q = 552, a = "A" }, { m = 1424, z = "Laderas de Trabalomas", x = 61.5, y = 20.9, n = "Recoger: Muestras de piedra (Vigilante Bel'varil)", q = 556, a = "A" }, { m = 1424, z = "Laderas de Trabalomas", x = 61.6, y = 20.9, n = "Recoger: Colarse en la cárcel (Magus Wordeen Vacuamirada)", q = 544, a = "A" }, { m = 1424, z = "Laderas de Trabalomas", x = 61.9, y = 19.6, n = "Recoger: La Sentencia (Sebo)", q = 676, a = "A" }, { m = 1424, z = "Laderas de Trabalomas", x = 61.6, y = 20.9, n = "Recoger: La llave de la ciudad (Magus Wordeen Vacuamirada)", q = 93680, a = "A" } } },
      { t = "Por las colinas del norte y del este de Trabalomas, los gólems y elementales de piedra sueltan [Muestras de piedra]. En la Atalaya de Dalaran, consigue las piezas de [Colarse en la cárcel] de sus magos y busca la llave mugrienta de [La llave de la ciudad] en el baúl del carcelero. La araña Helcular está en la cueva de las colinas del sur ([La venganza de Helcular]).", wp = { { m = 1416, z = "Montañas de Alterac", x = 16.0, y = 78.1, n = "Objetivo: Muestras de piedra", q = 556, a = "C" }, { m = 1416, z = "Montañas de Alterac", x = 19.6, y = 85.0, n = "Objetivo: Colarse en la cárcel", q = 544, a = "C" }, { m = 1424, z = "Laderas de Trabalomas", x = 44.4, y = 29.9, n = "Objetivo: La venganza de Helcular", q = 552, a = "C" } } },
      { t = "Entrega en el Molino Tarren [Muestras de piedra], [Colarse en la cárcel], [La llave de la ciudad] y [La venganza de Helcular].", wp = { { m = 1424, z = "Laderas de Trabalomas", x = 61.5, y = 20.9, n = "Entregar: Muestras de piedra (Vigilante Bel'varil)", q = 556, a = "T" }, { m = 1424, z = "Laderas de Trabalomas", x = 61.6, y = 20.9, n = "Entregar: Colarse en la cárcel (Magus Wordeen Vacuamirada)", q = 544, a = "T" }, { m = 1424, z = "Laderas de Trabalomas", x = 63.9, y = 19.7, n = "Entregar: La venganza de Helcular (Novicio Thaivand)", q = 552, a = "T" }, { m = 1424, z = "Laderas de Trabalomas", x = 61.6, y = 20.9, n = "Entregar: La llave de la ciudad (Magus Wordeen Vacuamirada)", q = 93680, a = "T" } } },
      { t = "Tras entregar [Colarse en la cárcel] y [La llave de la ciudad], acepta [Las patrullas de Dalaran] de Magus Wordeen Vacuamirada. Completa sus objetivos en Alterac y regresa al Molino Tarren.", wp = { { m = 1424, z = "Laderas de Trabalomas", x = 61.6, y = 20.9, n = "Recoger: Las patrullas de Dalaran (Magus Wordeen Vacuamirada)", q = 545, a = "A" }, { m = 1416, z = "Montañas de Alterac", x = 21, y = 58.5, n = "Objetivo: Las patrullas de Dalaran", q = 545, a = "C" }, { m = 1424, z = "Laderas de Trabalomas", x = 61.6, y = 20.9, n = "Entregar: Las patrullas de Dalaran (Magus Wordeen Vacuamirada)", q = 545, a = "T" } } }, -- REFUERZO_97 q=545
