      { t = "Al este, en Arathi, el puesto de Sentencia: entrega [La Sentencia] a Bombo Vil y acepta [Un llamamiento a las armas], [Magia demoníaca] (Tor'gan) y [Sentencia] (Gor'mul). Activa el vuelo con Urda.", wp = { { m = 1417, z = "Tierras Altas de Arathi", x = 74.2, y = 33.9, n = "Entregar: La Sentencia (Bombo Vil)", q = 676, a = "T" }, { m = 1417, z = "Tierras Altas de Arathi", x = 74.2, y = 33.9, n = "Recoger: Un llamamiento a las armas (Bombo Vil)", q = 677, a = "A" }, { m = 1417, z = "Tierras Altas de Arathi", x = 74.7, y = 36.3, n = "Recoger: Magia demoníaca (Tor'gan)", q = 671, a = "A" }, { m = 1417, z = "Tierras Altas de Arathi", x = 72.6, y = 33.9, n = "Recoger: Sentencia (Gor'mul)", q = 655, a = "A" }, { m = 1417, z = "Tierras Altas de Arathi", x = 73.0, y = 32.7, n = "Urda", npc = 2851 } }, comprobar = { vuelo = "Sentencia" } },
