  {
    titulo = "Vega de Tuercespina", min = 35, max = 38,
    entrenar = "Al 36: Tortura mental (rango 3), Peste devoradora (rango 3) y Palabra de poder: escudo (rango 6). Los tigres y los raptores de la Vega pegan fuerte: lleva siempre el escudo puesto. Talentos 35-39: Oscuridad (más daño de Sombra).",
    equipo = "Reúne las páginas de [Las verdes colinas de Tuercespina] mientras matas: el libro se entrega al 40. Mazmorras (opcional): las de tu nivel dan mucha experiencia, por sus enemigos y por sus misiones, y conviene hacerlas; tú decides si vas.",
    profesion = "En la Bahía del Botín, Grarnik Cortefino es sastre experto. Los trols de la Vega sueltan mucho paño de seda.",
    pasos = {
      { t = "Desde Entrañas o desde Orgrimmar coge el zepelín al Campamento Grom'gol (Vega de Tuercespina). Activa el vuelo con Thysta y pon la piedra de hogar con Tabernero Thulbek. Acepta [Caza para Yenniku] (Nimboya), [Collares de huesos sangrientos] y [El Arrecife Mortal] (Kin'weelay), [La defensa de Grom'gol] (Comandante Aggro'gosh) y [El encantamiento de Mok'thardin] (Clarividente Mok'thardin).", wp = { { m = 1434, z = "Vega de Tuercespina", x = 32.5, y = 29.4, n = "Thysta", npc = 1387 }, { m = 1434, z = "Vega de Tuercespina", x = 31.5, y = 29.8, n = "Tabernero Thulbek", npc = 5814 }, { m = 1434, z = "Vega de Tuercespina", x = 32.2, y = 27.7, n = "Recoger: Caza para Yenniku (Nimboya)", q = 581, a = "A" }, { m = 1434, z = "Vega de Tuercespina", x = 32.3, y = 27.7, n = "Recoger: Collares de huesos sangrientos (Kin'weelay)", q = 596, a = "A" }, { m = 1434, z = "Vega de Tuercespina", x = 32.3, y = 27.7, n = "Recoger: El Arrecife Mortal (Kin'weelay)", q = 629, a = "A" }, { m = 1434, z = "Vega de Tuercespina", x = 32.2, y = 28.9, n = "Recoger: La defensa de Grom'gol (Comandante Aggro'gosh)", q = 568, a = "A" }, { m = 1434, z = "Vega de Tuercespina", x = 32.1, y = 29.2, n = "Recoger: El encantamiento de Mok'thardin (Clarividente Mok'thardin)", q = 570, a = "A" } }, comprobar = { vuelo = "Grom'gol" } },
      { t = "Al norte, en la expedición de Nesingwary: acepta [Bienvenido a la jungla] y entrégala a Hemet Decautela. Acepta [Domina el tigre], [Domina la pantera] y [Domina el raptor].", wp = { { m = 1434, z = "Vega de Tuercespina", x = 35.7, y = 10.5, n = "Recoger: Bienvenido a la jungla (Barnil Jarropetra)", q = 583, a = "A" }, { m = 1434, z = "Vega de Tuercespina", x = 35.7, y = 10.8, n = "Entregar: Bienvenido a la jungla (Hemet Decautela)", q = 583, a = "T" }, { m = 1434, z = "Vega de Tuercespina", x = 35.6, y = 10.6, n = "Recoger: Domina el tigre (Ajeck Rouack)", q = 185, a = "A" }, { m = 1434, z = "Vega de Tuercespina", x = 35.5, y = 10.6, n = "Recoger: Domina la pantera (Sir S. J. Erlgadin)", q = 190, a = "A" }, { m = 1434, z = "Vega de Tuercespina", x = 35.7, y = 10.8, n = "Recoger: Domina el raptor (Hemet Decautela)", q = 194, a = "A" } } },
