R.talentosIntro = "Sombra para levear: Golpe de espíritu al 10, Tortura mental al 20, Abrazo vampírico al 25 y Forma de las Sombras al 40; después, Especialización en varitas y Disciplinas gemelas en Disciplina. Nombres en español con el inglés entre paréntesis."
R.talentos = {
  { d = 10, h = 14, rama = "Sombra", fila = 1, nombre = "Golpe de espíritu (Spirit Tap)", puntos = "5/5", nota = "Después de matar, tu Espíritu se duplica unos segundos: recuperas maná mucho más rápido y descansas menos.", icono = "Interface\\Icons\\Spell_Shadow_Requiem" },
  { d = 15, h = 16, rama = "Sombra", fila = 2, nombre = "Palabra de las Sombras: dolor mejorada (Improved Shadow Word: Pain)", puntos = "2/2", nota = "Tu daño en el tiempo dura 6 s más.", icono = "Interface\\Icons\\Spell_Shadow_ShadowWordPain" },
  { d = 17, h = 19, rama = "Sombra", fila = 2, nombre = "Explosión mental mejorada (Improved Mind Blast)", puntos = "3/5", nota = "Explosión mental se recarga antes. Con estos 10 puntos abres la fila 3.", icono = "Interface\\Icons\\Spell_Shadow_UnholyFrenzy" },
  { d = 20, h = 20, rama = "Sombra", fila = 3, nombre = "Tortura mental (Mind Flay)", puntos = "1/1", nota = "Daño de Sombra canalizado que además ralentiza: tu hechizo de relleno. Compra sus rangos al instructor.", icono = "Interface\\Icons\\Spell_Shadow_SiphonMana" },
  { d = 21, h = 22, rama = "Sombra", fila = 3, nombre = "Tortura mental mejorada (Improved Mind Flay)", puntos = "2/2", nota = "Nuevo en Forever: cada golpe de Tortura mental hace más daño que el anterior.", icono = "Interface\\Icons\\Spell_Shadow_SoulLeech_2" },
  { d = 23, h = 24, rama = "Sombra", fila = 2, nombre = "Explosión mental mejorada (Improved Mind Blast)", puntos = "5/5", nota = "Completa el talento. Con estos 15 puntos abres la fila 4.", icono = "Interface\\Icons\\Spell_Shadow_UnholyFrenzy" },
  { d = 25, h = 25, rama = "Sombra", fila = 4, nombre = "Abrazo vampírico (Vampiric Embrace)", puntos = "1/1", nota = "Te curas con parte del daño de Sombra que haces: póntelo en los enemigos que vayan a durar.", icono = "Interface\\Icons\\Spell_Shadow_UnsummonBuilding" },
  { d = 26, h = 28, rama = "Sombra", fila = 4, nombre = "Tejido de las Sombras (Shadow Weaving)", puntos = "3/3", nota = "Tus hechizos de Sombra hacen que el enemigo reciba más daño de Sombra, y se acumula.", icono = "Interface\\Icons\\Spell_Shadow_BlackPlague" },
  { d = 29, h = 29, rama = "Sombra", fila = 2, nombre = "Alcance de las Sombras (Shadow Reach)", puntos = "1/2", nota = "Más alcance para tus hechizos de Sombra. Con 20 puntos abres la fila 5.", icono = "Interface\\Icons\\Spell_Shadow_ChillTouch" },
  { d = 30, h = 30, rama = "Sombra", fila = 5, nombre = "Silencio (Silence)", puntos = "1/1", nota = "Corta el hechizo de un lanzador y lo deja sin lanzar unos segundos.", icono = "Interface\\Icons\\Spell_Shadow_ImpPhaseShift" },
  { d = 31, h = 32, rama = "Sombra", fila = 5, nombre = "Contagio devorador (Devouring Contagion)", puntos = "2/2", nota = "Nuevo: Peste devoradora cuesta menos maná y, si el enemigo muere con ella, salta a los que tiene cerca.", icono = "Interface\\Icons\\Spell_Shadow_DevouringPlague" },
  { d = 33, h = 33, rama = "Sombra", fila = 2, nombre = "Alcance de las Sombras (Shadow Reach)", puntos = "2/2", nota = "Completa el talento.", icono = "Interface\\Icons\\Spell_Shadow_ChillTouch" },
  { d = 34, h = 34, rama = "Sombra", fila = 1, nombre = "Enfoque de las Sombras (Shadow Focus)", puntos = "1/5", nota = "Tus hechizos de Sombra fallan menos. Con 25 puntos abres la fila 6.", icono = "Interface\\Icons\\Spell_Shadow_BurningSpirit" },
  { d = 35, h = 39, rama = "Sombra", fila = 6, nombre = "Oscuridad (Darkness)", puntos = "5/5", nota = "Más daño de Sombra. Con 30 puntos abres la fila 7.", icono = "Interface\\Icons\\Spell_Shadow_Twilight" },
  { d = 40, h = 40, rama = "Sombra", fila = 7, nombre = "Forma de las Sombras (Shadowform)", puntos = "1/1", nota = "Más daño de Sombra, tus hechizos de Sombra cuestan la mitad y recibes menos daño físico. En la forma no puedes curar.", icono = "Interface\\Icons\\Spell_Shadow_Shadowform" },
  { d = 41, h = 44, rama = "Sombra", fila = 1, nombre = "Enfoque de las Sombras (Shadow Focus)", puntos = "5/5", nota = "Completa el talento: desde el 40 los enemigos resisten más.", icono = "Interface\\Icons\\Spell_Shadow_BurningSpirit" },
  { d = 45, h = 46, rama = "Sombra", fila = 6, nombre = "Muerte prematura (Early Demise)", puntos = "2/2", nota = "Nuevo: Palabra de las Sombras: muerte hace más críticos a los enemigos con poca vida.", icono = "Interface\\Icons\\Spell_Shadow_DemonicFortitude" },
  { d = 47, h = 48, rama = "Disciplina", fila = 1, nombre = "Especialización en varitas (Wand Specialization)", puntos = "2/2", nota = "Más daño con la varita.", icono = "Interface\\Icons\\INV_Wand_01" },
  { d = 49, h = 53, rama = "Disciplina", fila = 1, nombre = "Disciplinas gemelas (Twin Disciplines)", puntos = "5/5", nota = "Nuevo: tus hechizos instantáneos hacen más daño y curan más (Palabra de las Sombras: dolor y muerte, Peste devoradora y el escudo).", icono = "Interface\\Icons\\Spell_Holy_SealOfVengeance" },
  { d = 54, h = 58, rama = "Sombra", fila = 4, nombre = "Inspiración oscura (Dark Inspiration)", puntos = "5/5", nota = "Nuevo: Explosión mental y Tortura mental te dan más Espíritu a ti y a tu grupo unos segundos.", icono = "Interface\\Icons\\Spell_Warlock_DemonSoul" },
  { d = 59, h = 60, rama = "Disciplina", fila = 2, nombre = "Fuerza mental (Mental Strength)", puntos = "2/5", nota = "Más Intelecto. Total al 60: 42 Sombra / 9 Disciplina.", icono = "Interface\\Icons\\Spell_Nature_EnchantArmor" },
}

